def cache_sim(capacity, ttl, ops):
    from collections import OrderedDict

    cache = OrderedDict()  # key -> (value, write_time)
    results = []

    for op in ops:
        if op[0] == 'put':
            _, t, key, value = op

            # Remove expired entries
            keys_to_remove = [k for k, (_, write_time) in cache.items() if write_time + ttl <= t]
            for k in keys_to_remove:
                del cache[k]

            # If key exists, remove it (will re-add at end to mark as most recent)
            if key in cache:
                del cache[key]
            else:
                # Key doesn't exist, check if we need to evict
                if len(cache) >= capacity:
                    # Evict least recently used (first item in OrderedDict)
                    cache.popitem(last=False)

            # Add the new entry (becomes most recent)
            cache[key] = (value, t)

        elif op[0] == 'get':
            _, t, key = op

            # Remove expired entries
            keys_to_remove = [k for k, (_, write_time) in cache.items() if write_time + ttl <= t]
            for k in keys_to_remove:
                del cache[k]

            # Check if key exists in cache
            if key in cache:
                value, write_time = cache[key]
                # Move to end (most recently used)
                cache.move_to_end(key)
                results.append(value)
            else:
                results.append(-1)

    return results

